  const NAMES = { NA: '북아메리카', SA: '남아메리카', EU: '유라시아', AF: '아프리카', IN: '인도', AU: '오스트레일리아', AN: '남극 대륙', GL: '그린란드' };
  const PAL = { NA: ['#f4a261', '#a85d1f'], SA: ['#86d36f', '#3c8a35'], EU: ['#f6d860', '#a98a1c'], AF: ['#e2a15f', '#97601f'], IN: ['#f08ab8', '#a53a72'], AU: ['#b9a3f7', '#6a4fc2'], AN: ['#f5f9fd', '#8ea4bb'], GL: ['#f7b98b', '#a85d1f'] };
  const REF = { NA: [-100, 46], SA: [-60, -12], AF: [20, 6], EU: [75, 55], IN: [78, 22], AU: [134, -25], AN: [60, -80], GL: [-42, 72] };
  const DRAG = ['AF', 'EU', 'SA', 'NA', 'IN', 'AU'];            // 끌 수 있는 조각 (그린란드는 북아메리카와 함께)
  const PC = {};
