        ctx.beginPath(); let any = false;
        pc.rings.forEach((rg) => { if (visibleOff(rg, cLon, off)) { ringPath(ctx, rg, M, cLon, off, dx + sh, dy + sy); any = true; } });
        if (!any) continue;
