    ctx.fillStyle = 'rgba(255,255,255,.96)'; roundRect(ctx, H.x, H.y, H.w, H.h, 14); ctx.fill();
    ctx.textAlign = 'left'; ctx.fillStyle = '#1b2333'; ctx.font = '700 ' + Math.round(16 * Math.min(1.1, L.fs)) + 'px ' + FONT;
    const msg = total === 0 ? '📍 [자료 찍기]를 눌러 지진과 화산이 일어난 곳을 지도에 하나씩 쌓아 봐요.' : total < 300 ? '자료를 더 쌓아 보세요. 점들이 어떻게 모이나요?' : total < 900 ? '🔎 점들이 아무 곳에나 있나요? 모여 있는 모양을 살펴봐요.' : '🔎 지진과 화산이 띠 모양으로 이어져 있는 것이 보이나요?';
    const lines = wrapLines(ctx, msg, H.w - 28);
    lines.forEach((ln, i) => ctx.fillText(ln, H.x + 14, H.y + 26 + i * 22));
    let y = H.y + 26 + lines.length * 22 + 16, x = H.x + 14;
    // 범례
    ctx.fillStyle = 'rgba(225,29,72,.7)'; ctx.beginPath(); ctx.arc(x + 8, y, 7, 0, TAU); ctx.fill(); ctx.strokeStyle = '#fff'; ctx.lineWidth = 1; ctx.stroke();
    ctx.fillStyle = '#26364f'; ctx.font = 'bold ' + Math.round(14 * Math.min(1.1, L.fs)) + 'px ' + FONT; ctx.fillText('지진 ' + D.nq + '개', x + 22, y + 5);
    const w1 = ctx.measureText('지진 ' + D.nq + '개').width + 40;
    x += w1;
    ctx.fillStyle = '#7f1d1d'; ctx.beginPath(); ctx.moveTo(x + 8, y - 8); ctx.lineTo(x, y + 6); ctx.lineTo(x + 16, y + 6); ctx.closePath(); ctx.fill(); ctx.strokeStyle = '#fff3d6'; ctx.lineWidth = 1; ctx.stroke();
    ctx.fillStyle = '#26364f'; ctx.fillText('화산 ' + D.nv + '개', x + 24, y + 5);
    x += ctx.measureText('화산 ' + D.nv + '개').width + 42;
    ctx.fillStyle = '#5d6879'; ctx.font = '600 ' + Math.round(13 * Math.min(1.1, L.fs)) + 'px ' + FONT;
