    if (USE_LAYERS && Math.abs(S.cLon - S.cLonT) < 0.05) {                        // 가만히 있을 땐 화살표 모양을 한 장으로 복사
      const ly = layerFor(V, 'arrows'), sig = L.key + '|' + cLon.toFixed(2);
      if (ly.sig !== sig) { ly.sig = sig; layerClear(V, ly); const g = layerCtx(V, ly); list.forEach((q) => arrowBody(g, q[0], q[1], q[2], q[3], w, '#26364f')); }
      blit(ctx, ly);
    } else list.forEach((q) => arrowBody(ctx, q[0], q[1], q[2], q[3], w, '#26364f'));
    list.forEach((q) => arrowFlow(ctx, q[0], q[1], q[2], q[3], w, P.flow));
