    const c = cityCount();
    // 경계 근처 비율
    let near = 0, cnt = 0;
    for (let i = 0; i < D.nq; i++) { near += qNear[i]; cnt++; }
    for (let i = 0; i < D.nv; i++) { near += vNear[i]; cnt++; }
